:root {
  --cream: #f2e8d5;
  --parchment: #e0cda8;
  --ink: #2c1f0e;
  --ink-light: #5a3e28;
  --rust: #9b3a1a;
  --rust-light: #c4541f;
  --forest: #2e5035;
  --gold: #b08730;
  --gold-light: #d4a843;
  --muted: #8a7560;
  --tag-bg: #dbc898;
  --border: #b09265;
  --stamp-bg: #1e3a28;
  --pill-bg: #2e5035;
  --pill-text: #d4e8d4;
}

article.repair-ticket {
  width: 480px;
  background: var(--cream);
  border: 2px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.ticket-header {
  background: var(--ink);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 3px solid var(--gold);
}

.ticket-badge {
  font-size: 9px;
  font-weight: 700;
  color: var(--gold-light);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border: 1px solid var(--gold);
  border-radius: 2px;
  padding: 2px 5px;
  line-height: 1;
}

.ticket-number {
  font-size: 18px;
  font-weight: 800;
  color: var(--gold-light);
  letter-spacing: 0.04em;
  flex-shrink: 0;
}

.ticket-title {
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: 2px;
}

.title-main {
  font-size: 13px;
  font-weight: 700;
  color: var(--cream);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  line-height: 1;
}

.title-sub {
  font-size: 9px;
  color: var(--muted);
  letter-spacing: 0.04em;
  line-height: 1;
}

.ticket-stamp {
  font-size: 10px;
  font-weight: 800;
  color: var(--stamp-bg);
  background: var(--gold-light);
  padding: 4px 8px;
  border-radius: 2px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  transform: rotate(-2deg);
  flex-shrink: 0;
}

.ticket-body {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px 14px;
  border-bottom: 2px dashed var(--border);
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.info-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
  border-left: 2px solid var(--gold);
  padding-left: 7px;
}

.info-label {
  font-size: 8px;
  font-weight: 700;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  line-height: 1;
}

.info-value {
  font-size: 11px;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.2;
}

.fault-section {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.fault-label {
  font-size: 9px;
  font-weight: 800;
  color: var(--rust);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  border-bottom: 1px solid var(--parchment);
  padding-bottom: 3px;
}

.fault-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.fault-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--ink-light);
  line-height: 1.2;
}

.fault-dot {
  width: 6px;
  height: 6px;
  background: var(--rust);
  border-radius: 50%;
  flex-shrink: 0;
}

.parts-row {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--parchment);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 8px 10px;
}

.gear-icon {
  font-size: 28px;
  color: var(--gold);
  margin: 0;
  line-height: 1;
  flex-shrink: 0;
}

.parts-detail {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
}

.parts-label {
  font-size: 8px;
  font-weight: 800;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.parts-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.tag {
  font-size: 9px;
  font-weight: 700;
  color: var(--ink);
  background: var(--tag-bg);
  border: 1px solid var(--gold);
  border-radius: 2px;
  padding: 2px 6px;
  letter-spacing: 0.03em;
}

.cost-block {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  border-left: 1px solid var(--border);
  padding-left: 10px;
}

.cost-label {
  font-size: 8px;
  font-weight: 700;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.cost-value {
  font-size: 16px;
  font-weight: 800;
  color: var(--forest);
  line-height: 1;
  letter-spacing: 0.02em;
}

.ticket-footer {
  background: var(--parchment);
  display: flex;
  align-items: center;
  gap: 0;
  padding: 8px 14px;
}

.footer-left {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.craftsman-label {
  font-size: 8px;
  font-weight: 700;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.craftsman-name {
  font-size: 12px;
  font-weight: 800;
  color: var(--ink);
  font-style: italic;
}

.footer-divider {
  width: 1px;
  height: 32px;
  background: var(--border);
  margin: 0 12px;
  flex-shrink: 0;
}

.footer-center {
  display: flex;
  align-items: center;
  flex: 1;
  justify-content: center;
}

.shop-address {
  font-size: 9px;
  color: var(--muted);
  text-align: center;
  letter-spacing: 0.04em;
}

.footer-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 3px;
  flex: 1;
}

.status-label {
  font-size: 8px;
  font-weight: 700;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.status-pill {
  font-size: 9px;
  font-weight: 800;
  color: var(--pill-text);
  background: var(--pill-bg);
  border-radius: 20px;
  padding: 3px 10px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
